**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int liczba;
    int najLiczba = 0, najRoznica = -1;
    while (plik >> liczba) {
        int kopia = liczba;
        int maxC = 0, minC = 9;
        while (kopia > 0) {
            int c = kopia % 10;
            if (c > maxC) maxC = c;
            if (c < minC) minC = c;
            kopia /= 10;
        }
        int roznica = maxC - minC;
        cout << liczba << ": max cyfra=" << maxC
             << ", min cyfra=" << minC
             << ", roznica=" << roznica << endl;
        if (roznica > najRoznica) {
            najRoznica = roznica;
            najLiczba = liczba;
        }
    }
    cout << "Najwieksza roznica: " << najLiczba
         << " (roznica=" << najRoznica << ")" << endl;
    return 0;
}
```

**Wyjasnienie**: Dla kazdej liczby wyodrebniamy cyfry i sledzimy max/min. Inicjalizacja maxC=0 i minC=9 gwarantuje, ze kazda napotkana cyfra (0-9) poprawnie zaktualizuje wartosci. Roznica max-min mowi, jak bardzo cyfry sa rozproszone.

